-- pipeline/outlet-failed
-- An outlet's feed could not be read: keeps the error and counts failures in a row.
--
-- Parameters, with the example values used to render this file:
--   $1 = "HTTP 503"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

update "outlets"
set "last_error" = $1, "consecutive_failures" = "outlets"."consecutive_failures" + 1, "updated_at" = now()
where "outlets"."id" = $2
returning "consecutive_failures";
